"use client";

import {
  filePickerTriggerDefaults,
  resolveFilePickerDescriptor,
  resolveFilePickerSelection,
  validateFilePickerTriggers,
  type FilePickerCandidate,
  type FilePickerDescriptor,
  type FilePickerSelectionResult,
} from "@hjmds/design-contracts/components/file-picker";
import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type ChangeEvent,
  type DragEvent,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { classNames, composeRefs } from "./internal.js";
import type { HjmCompositionStyleProp } from "./composition-style.js";

export type FilePickerProps = Omit<HTMLAttributes<HTMLDivElement>, "children" | "onSelect"> &
  Readonly<{
    descriptor: FilePickerDescriptor;
    label: ReactNode;
    buttonLabel: string;
    dropzoneLabel: ReactNode;
    /**
     * `files` maps each accepted candidate id to the browser `File`, so the product can read or upload
     * the bytes it accepted. Before this a Web product had no access to the File and fell back to a raw
     * `<input type="file">` (2026-10-17 mockup studio review). Native products already own the file
     * reference through their `onPick` adapter, so Native keeps the single-argument callback.
     */
    onSelect: (result: FilePickerSelectionResult, files: ReadonlyMap<string, File>) => void;
    existingCount?: number;
    disabled?: boolean;
    hint?: ReactNode;
    error?: ReactNode;
    inputId?: string;
    getCandidateId?: (file: File, index: number) => string;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

function defaultCandidateId(file: File, index: number): string {
  return `${file.name}:${file.size}:${file.lastModified}:${index}`;
}

/** Native file input plus an optional Web dropzone sharing one selection resolver. */
export const FilePicker = forwardRef<HTMLDivElement, FilePickerProps>(function FilePicker(
  {
    descriptor,
    label,
    buttonLabel,
    dropzoneLabel,
    onSelect,
    existingCount = 0,
    disabled = false,
    hint,
    error,
    inputId,
    getCandidateId = defaultCandidateId,
    className,
    layoutStyle,
    ...props
  },
  ref,
) {
  validateFilePickerTriggers("web", filePickerTriggerDefaults.web);
  const resolved = resolveFilePickerDescriptor(descriptor);
  const generatedId = useId();
  const id = inputId ?? `hjm-file-${generatedId.replaceAll(":", "")}`;
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);
  useEffect(() => { if (disabled) setDragging(false); }, [disabled]);

  const commit = (files: FileList | readonly File[]) => {
    // The OS dialog may finish after the owner locks this field. Empty input
    // changes represent no selection and must not erase a product's file list.
    if (disabled || files.length === 0) return;
    const sources = Array.from(files);
    const candidates: FilePickerCandidate[] = sources.map((file, index) => ({
      id: getCandidateId(file, index),
      name: file.name,
      mimeType: file.type,
      sizeBytes: file.size,
    }));
    const result = resolveFilePickerSelection(candidates, resolved, existingCount);
    const accepted = new Set(result.accepted.map(candidate => candidate.id));
    onSelect(result, new Map(candidates.flatMap((candidate, index) => accepted.has(candidate.id) ? [[candidate.id, sources[index]!] as const] : [])));
  };
  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    try { if (event.currentTarget.files) commit(event.currentTarget.files); }
    finally { event.currentTarget.value = ""; }
  };
  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    if (!disabled && event.dataTransfer.files.length > 0) commit(event.dataTransfer.files);
  };

  return (
    <div {...props} style={{ ...props.style, ...layoutStyle }} ref={composeRefs(ref)} className={classNames("hjm-file-picker", className)} data-dragging={(!disabled && dragging) || undefined} data-invalid={error !== undefined || undefined}>
      <span className="hjm-file-picker__label" id={`${id}-label`}>{label}</span>
      {/*
        The visible button below is the keyboard entry point. Before 1.5.0 this
        hidden input was a second, unnamed tab stop (the label span was not
        associated with it), so a screen reader announced a nameless "file"
        control. It stays in the accessibility tree for virtual cursors, named
        by the label, and leaves the tab order.
      */}
      <input
        accept={resolved.accept?.join(",")}
        aria-labelledby={`${id}-label`}
        className="hjm-visually-hidden"
        disabled={disabled}
        id={id}
        tabIndex={-1}
        multiple={resolved.mode === "multiple"}
        onChange={handleChange}
        ref={inputRef}
        type="file"
      />
      <div
        className="hjm-file-picker__dropzone"
        onDragEnter={(event) => { event.preventDefault(); if (!disabled) setDragging(true); }}
        onDragLeave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setDragging(false); }}
        onDragOver={(event) => event.preventDefault()}
        onDrop={handleDrop}
      >
        <span>{dropzoneLabel}</span>
        <button disabled={disabled} onClick={() => inputRef.current?.click()} type="button">{buttonLabel}</button>
      </div>
      {hint === undefined ? null : <span className="hjm-file-picker__hint">{hint}</span>}
      {error === undefined ? null : <span className="hjm-file-picker__error" role="alert">{error}</span>}
    </div>
  );
});
